//! Closed original MSJZ04. Printed red/purple/neutral construction, pre-hand
//! sealing, and an optional paid release observed from a real host death.
use crate::{catalog,engine::RuleResult,model::*,rules::*,black_next20::BlackDeathObservation,society::{SocietyDefinition,SocietyDeckConstraint}};
use std::collections::BTreeSet;
pub(crate) const ID:&str="MSJZ04";
pub(crate) const DEATH:&str="msjz04-host-death";
const OPEN:&str="msjz04-opening";
const DONE:&str="msjz04-opening-done";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn nightmare(c:&Card)->bool{let d=catalog::card(&c.definition);d.kind=="character"&&d.subtypes.iter().any(|s|s=="梦魔")}
pub(crate) fn definition()->Definition{with_abilities(vec![ability(DEATH,"本方宿主死亡：支付1，将一个封印梦魔暗藏入原地区",Timing::Fast,vec![],vec![],vec![Op::MSJZ04Release{observation:None}],Some(Event::MSJZ04HostDeath))])}
pub(crate) fn society()->SocietyDefinition{let mut card:catalog::CardDefinition=serde_json::from_value(serde_json::json!({"id":ID,"name":"破茧者教团","subtitle":"阿塞纳卡","kind":"society","type":"秘社/秘密教派","subtypes":["秘密教派"],"color":"红","society":"破茧者教团","unique":true,"supported":false,"text":"构筑只允许红、紫、中立。抓取起始手牌前，从牌库寻找至多五张名称不同的梦魔角色牌，封印在本秘社上，然后洗牌。本方宿主角色死亡时，可以支付1，将一张封印在本秘社上的梦魔角色牌以暗藏者状态置于该地区。"})).unwrap();card.abilities=definition().abilities.iter().map(|a|catalog::AbilitySummary{key:a.key.clone(),label:a.label.clone(),timing:"fast".into(),costs:a.costs.clone(),triggered:true}).collect();SocietyDefinition{card,subtitle:"阿塞纳卡".into(),printed_cost:None,starting_hand:6,deck_constraints:vec![SocietyDeckConstraint::RedPurpleNeutral],unresolved_abilities:Default::default()}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("msjz04-")||a.event==Some(Event::MSJZ04HostDeath)||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(|o|matches!(o,Op::MSJZ04Release{..}))}
fn related_frame(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("msjz04-")||f.steps.iter().any(|s|matches!(s.op,Op::MSJZ04Release{..}))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.remove(0);if let [Op::MSJZ04Release{observation}]=a.ops.as_slice(){expected.ops=vec![Op::MSJZ04Release{observation:observation.clone()}];}if id!=ID||!same(a,&expected){return Err("破茧者须保留宿主死亡、费用1及原释放程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("破茧者定义不可改写或移植".into());}Ok(())}
impl Game{
 fn msjz04_live(&self,seat:usize)->bool{self.players.get(seat).is_some_and(|p|!p.eliminated&&p.society_zone.card.as_ref().is_some_and(|c|c.definition==ID&&!c.face_down&&c.owner==seat&&c.controller==seat))}
 pub(crate) fn msjz04_defer_hand(&mut self,seat:usize)->bool{if !self.msjz04_live(seat){return false;}self.players[seat].society_zone.used_once_per_game.insert(OPEN.into());self.effects.push_back(Effect::MSJZ04Opening{seat});true}
 fn msjz04_open_valid(&self,seat:usize)->RuleResult<()>{if !self.msjz04_live(seat)||self.turn!=1||!self.players[seat].hand.is_empty()||self.players[seat].society_zone.used_once_per_game.iter().filter(|k|k.as_str()==OPEN).count()!=1||self.players[seat].society_zone.used_once_per_game.iter().any(|k|k==DONE){return Err("破茧者起手前选择缺唯一原开局授权".into());}Ok(())}
 fn msjz04_open_options(&self,seat:usize)->Vec<ChoiceOption>{self.players[seat].deck.iter().filter(|c|nightmare(c)).map(|c|self.option(c,seat,None,None)).collect()}
 pub(crate) fn msjz04_open(&mut self,seat:usize)->RuleResult<()>{self.msjz04_open_valid(seat)?;let options=self.msjz04_open_options(seat);if options.is_empty(){return self.msjz04_open_finish(seat,&[]);}self.choice(seat,"msjz04-opening","破茧者：封印至多五个不同名称的梦魔".into(),options,0,5,None,ChoiceResolution::MSJZ04Opening{seat});Ok(())}
 pub(crate) fn msjz04_open_finish(&mut self,seat:usize,ids:&[String])->RuleResult<()>{self.msjz04_open_valid(seat)?;let mut names=BTreeSet::new();if ids.len()>5||ids.iter().collect::<BTreeSet<_>>().len()!=ids.len(){return Err("至多五张不同实例且名称不同".into());}for id in ids{let c=self.players[seat].deck.iter().find(|c|&c.id==id&&nightmare(c)).ok_or("必须选择本人牌库中的梦魔角色")?;if !names.insert(&catalog::card(&c.definition).name){return Err("所选梦魔名称不能相同".into());}}
 for id in ids{let i=self.players[seat].deck.iter().position(|c|&c.id==id).unwrap();let c=self.players[seat].deck.remove(i);self.seal_card_on_valid_host(c,seat,&format!("society:p{seat}"));}let mut deck=std::mem::take(&mut self.players[seat].deck);self.shuffle(&mut deck);self.players[seat].deck=deck;self.players[seat].society_zone.used_once_per_game.insert(DONE.into());self.draw(seat,6)
 }
 pub(crate) fn msjz04_sources(&self)->Vec<SourceSnapshot>{(0..self.players.len()).filter(|s|self.msjz04_live(*s)).map(|s|self.source_snapshot(self.players[s].society_zone.card.as_ref().unwrap(),None)).collect()}
 pub(crate) fn msjz04_observe(&mut self,sources:&[SourceSnapshot],o:&BlackDeathObservation){if !o.subtypes.iter().any(|s|s=="宿主"){return;}for source in sources{if source.card.controller!=o.dead.controller{continue;}let mut a=definition().abilities.remove(0);a.ops=vec![Op::MSJZ04Release{observation:Some(o.clone())}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor:source.card.controller,source:source.clone(),ability:a}});}}
 fn msjz04_source(&self,actor:usize,s:&SourceSnapshot,ops:&[Op])->RuleResult<()>{let c=&s.card;if actor>=self.players.len()||c.definition!=ID||c.owner!=actor||c.controller!=actor||c.face_down||!self.mystic_instance_valid(&c.id)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("破茧者原秘社来源损坏".into());}let[Op::MSJZ04Release{observation:Some(o)}]=ops else{return Err("宿主触发缺实际死亡观察".into());};if o.turn!=self.turn||o.dead.controller!=actor||o.dead.owner>=self.players.len()||o.dead.face_down||catalog::card(&o.dead.definition).kind!="character"||!o.subtypes.iter().any(|s|s=="宿主")||o.region>=self.regions.len()||!self.mystic_instance_valid(&o.region_instance)||!self.mystic_instance_number(&o.event_id).zip(self.mystic_instance_number(&o.dead.id)).is_some_and(|(event,dead)|event>dead){return Err("破茧者观察不是原本方正面宿主死亡".into());}self.mobility_immutable_identity(c)?;self.mobility_immutable_identity(&o.dead)}
 pub(crate) fn validate_msjz04_declaration(&self,d:&Declaration)->RuleResult<()>{if d.source.card.definition==ID||related(&d.ability){validate_ability(&d.source.card.definition,&d.ability)?;self.msjz04_source(d.actor,&d.source,&d.ability.ops)?;}Ok(())}
 pub(crate) fn validate_msjz04_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !related_frame(f){return Ok(());}self.validate_resource_frame(f)?;let ops=f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>();self.msjz04_source(f.actor,&f.source,&ops)?;if f.ability_key!=DEATH||!self.mystic_instance_valid(&f.frame_id)||f.steps.len()!=1||f.steps[0].context!=f.actor||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!f.targets.is_empty()||f.chosen_region.is_some()||!(f.already_paid.is_empty()&&f.resource_payments.is_empty()||f.cursor==1&&matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)==1&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())){return Err("破茧者死亡帧费用、阶段或程序损坏".into());}Ok(())}
 fn msjz04_release_options(&self,f:&ResolutionFrame)->Vec<ChoiceOption>{let[Step{op:Op::MSJZ04Release{observation:Some(o)},..}]=f.steps.as_slice()else{return vec![];};if self.players[f.actor].eliminated||!self.region_live(o.region)||self.regions[o.region].card.id!=o.region_instance||self.players[f.actor].society_zone.card.as_ref().is_none_or(|c|c.id!=f.source.card.id){return vec![];}self.sealed_cards.iter().filter(|s|s.host_id==format!("society:p{}",f.actor)&&nightmare(&s.card)).map(|s|self.option(&s.card,f.actor,None,None)).collect()}
 pub(crate) fn msjz04_release(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_msjz04_frame(&f)?;if f.cursor!=1{return Err("释放只在原帧结算阶段".into());}if f.already_paid.is_empty(){if self.resources(f.actor)>=1{self.choice(f.actor,"payment","破茧者：可以支付1费用释放梦魔".into(),vec![ChoiceOption{id:"pay".into(),label:"支付1费用".into(),card:None}],0,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::MSJZ04Pay});}return Ok(());}let options=self.msjz04_release_options(&f);if !options.is_empty(){self.choice(f.actor,"sealed","破茧者：选择一个封印梦魔暗藏入宿主原地区".into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::MSJZ04Release});}Ok(())}
 pub(crate) fn msjz04_pay(&mut self,mut f:ResolutionFrame,seat:usize,ids:&[String])->RuleResult<()>{self.validate_msjz04_frame(&f)?;if f.cursor!=1||seat!=f.actor||!f.already_paid.is_empty()||ids.len()>1||ids.first().is_some_and(|s|s!="pay"){return Err("须在原效果中选择支付1".into());}if ids.is_empty(){return Ok(());}let p=self.capture_money(seat,1)?;let(paid,resources)=crate::step_resources::unpack_payments(vec![p]);f.already_paid=paid;f.resource_payments=resources;self.msjz04_release(f)}
 pub(crate) fn msjz04_release_finish(&mut self,f:&ResolutionFrame,seat:usize,ids:&[String])->RuleResult<()>{self.validate_msjz04_frame(f)?;if f.cursor!=1||f.already_paid.is_empty()||seat!=f.actor||ids.len()!=1||!self.msjz04_release_options(f).iter().any(|o|o.id==ids[0]){return Err("必须选择原秘社当前封印的一个梦魔".into());}let[Step{op:Op::MSJZ04Release{observation:Some(o)},..}]=f.steps.as_slice()else{unreachable!()};let i=self.sealed_cards.iter().position(|s|s.card.id==ids[0]).unwrap();let c=self.sealed_cards.remove(i).card;let mut c=self.fresh(c);c.controller=seat;c.face_down=true;self.apply_hidden_entry_slow(&mut c);self.regions[o.region].cards.push(c);Ok(())}
 pub(crate) fn validate_msjz04_state(&self)->RuleResult<()>{let mut openings=BTreeSet::new();let mut events=BTreeSet::new();let mut check=|actor,source:&SourceSnapshot,ops:&[Op]|->RuleResult<()>{if let[Op::MSJZ04Release{observation:Some(o)}]=ops{if !events.insert((actor,source.card.id.clone(),o.event_id.clone())){return Err("宿主同次死亡重复续体".into());}}Ok(())};
 for e in &self.effects{match e{Effect::MSJZ04Opening{seat}=>{self.msjz04_open_valid(*seat)?;if !openings.insert(*seat){return Err("重复起手封印".into());}},Effect::Declare{declaration:d}=>{self.validate_msjz04_declaration(d)?;check(d.actor,&d.source,&d.ability.ops)?;},Effect::Frame{frame:f}=>{self.validate_msjz04_frame(f)?;check(f.actor,&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;},_=>{}}}
 for i in &self.stack{if let Some(f)=&i.frame{self.validate_msjz04_frame(f)?;if related_frame(f){if i.card.is_some()||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.is_some()||f.cursor!=0{return Err("破茧者原堆叠外壳损坏".into());}check(f.actor,&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;}}}
 if let Some(p)=&self.pending{let own=match &p.resolution{ChoiceResolution::MSJZ04Opening{..}=>true,ChoiceResolution::Declare{declaration:d,..}=>d.source.card.definition==ID||related(&d.ability),ChoiceResolution::Frame{frame:f,choice}=>related_frame(f)||matches!(choice,FrameChoice::MSJZ04Pay|FrameChoice::MSJZ04Release),_=>false};if own&&(!self.mystic_instance_valid(&p.choice.id)||p.choice.amount.is_some()||!p.choice.preview_cards.is_empty()||p.choice.description!="选择符合数量限制的选项，然后确认。"){return Err("破茧者待选元数据损坏".into());}match &p.resolution{
 ChoiceResolution::MSJZ04Opening{seat}=>{self.msjz04_open_valid(*seat)?;if !openings.insert(*seat)||p.seat!=*seat||p.choice.player_id!=player_id(*seat)||p.choice.kind!="msjz04-opening"||p.choice.title!="破茧者：封印至多五个不同名称的梦魔"||p.choice.min!=Some(0)||p.choice.max!=Some(5)||p.choice.allow_decline!=Some(true)||!same(&p.choice.options,&self.msjz04_open_options(*seat)){return Err("破茧者起手待选损坏".into());}},
 ChoiceResolution::Declare{declaration:d,stage}=>{self.validate_msjz04_declaration(d)?;if d.source.card.definition==ID {let expected=vec![ChoiceOption{id:"accept".into(),label:"发动触发能力".into(),card:None}];if !matches!(stage,DeclareChoice::Accept)||p.seat!=d.actor||p.choice.player_id!=player_id(d.actor)||p.choice.kind!="trigger"||p.choice.title!=format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label)||p.choice.min!=Some(0)||p.choice.max!=Some(1)||p.choice.allow_decline!=Some(true)||!same(&p.choice.options,&expected){return Err("破茧者原可选死亡声明损坏".into());}}check(d.actor,&d.source,&d.ability.ops)?;},
 ChoiceResolution::Frame{frame:f,choice:FrameChoice::MSJZ04Pay}=>{self.validate_msjz04_frame(f)?;if f.source.card.definition!=ID||f.cursor!=1||!f.already_paid.is_empty()||p.seat!=f.actor||p.choice.player_id!=player_id(f.actor)||p.choice.kind!="payment"||p.choice.title!="破茧者：可以支付1费用释放梦魔"||p.choice.min!=Some(0)||p.choice.max!=Some(1)||p.choice.allow_decline!=Some(true)||self.resources(f.actor)<1||!same(&p.choice.options,&vec![ChoiceOption{id:"pay".into(),label:"支付1费用".into(),card:None}]){return Err("破茧者效果支付待选损坏".into());}check(f.actor,&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;},
 ChoiceResolution::Frame{frame:f,choice}if related_frame(f)||matches!(choice,FrameChoice::MSJZ04Release)=>{self.validate_msjz04_frame(f)?;if !related_frame(f)||f.cursor!=1||f.already_paid.is_empty()||!matches!(choice,FrameChoice::MSJZ04Release)||p.seat!=f.actor||p.choice.player_id!=player_id(f.actor)||p.choice.kind!="sealed"||p.choice.title!="破茧者：选择一个封印梦魔暗藏入宿主原地区"||p.choice.min!=Some(1)||p.choice.max!=Some(1)||p.choice.allow_decline!=Some(false)||self.msjz04_release_options(f).is_empty()||!same(&p.choice.options,&self.msjz04_release_options(f)){return Err("破茧者释放待选损坏".into());}check(f.actor,&f.source,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>())?;},_=>{}}}for p in &self.players{if p.society_zone.used_once_per_game.contains(OPEN)&&!p.society_zone.used_once_per_game.contains(DONE)&&!openings.contains(&p.seat){return Err("破茧者起手前续体丢失".into());}}Ok(())}
}
